<?php
declare(strict_types=1);require_once __DIR__.'/includes/init.php';require_role('encargado');$pageTitle='Reportes y exportación';$p=db();$turn=manager_turn_id();
$q=$p->prepare("SELECT t.id,t.tipo_problema,t.urgencia,t.estado,t.creado_en,s.nombre sala,CONCAT(u.nombre,' ',u.apellido) docente FROM tickets t JOIN salas s ON s.id=t.sala_id JOIN usuarios u ON u.id=t.docente_id WHERE t.turno_id=:t ORDER BY t.creado_en DESC LIMIT 20");$q->execute(['t'=>$turn]);$tickets=$q->fetchAll();
$q=$p->prepare("SELECT ss.checkin_en,ss.checkout_en,s.nombre sala,CONCAT(u.nombre,' ',u.apellido) docente FROM sesiones_sala ss JOIN salas s ON s.id=ss.sala_id JOIN usuarios u ON u.id=ss.docente_id JOIN usuario_turnos ut ON ut.usuario_id=u.id AND ut.turno_id=:t WHERE ut.eliminado_en IS NULL ORDER BY ss.checkin_en DESC LIMIT 20");$q->execute(['t'=>$turn]);$sessions=$q->fetchAll();
$counts=['tickets'=>count($tickets),'equipos'=>(int)$p->query("SELECT COUNT(*) FROM equipos WHERE activo=1 AND eliminado_en IS NULL")->fetchColumn(),'salas'=>(int)$p->query("SELECT COUNT(*) FROM salas WHERE activa=1 AND eliminado_en IS NULL")->fetchColumn()];
$q=$p->prepare("SELECT COUNT(DISTINCT u.id) FROM usuarios u JOIN usuario_turnos ut ON ut.usuario_id=u.id WHERE u.rol='docente' AND u.eliminado_en IS NULL AND ut.turno_id=:t AND ut.activo=1 AND ut.eliminado_en IS NULL");$q->execute(['t'=>$turn]);$counts['profesores']=(int)$q->fetchColumn();require __DIR__.'/includes/header.php';
?>
<section class="report-actions card no-print"><div class="card-body"><div><p class="eyebrow">Turno <?=e(manager_turn_name())?></p><h2>Centro de reportes</h2><p class="text-muted">Descargá datos en CSV o imprimí esta vista para guardarla como PDF desde el navegador.</p></div><div class="report-action-buttons"><button class="btn btn-primary" onclick="window.print()">Imprimir / Guardar PDF</button></div></div></section>
<section class="grid grid-4 mt-3"><article class="metric-panel"><span>Profesores</span><strong><?=$counts['profesores']?></strong></article><article class="metric-panel"><span>Salas</span><strong><?=$counts['salas']?></strong></article><article class="metric-panel"><span>Equipos</span><strong><?=$counts['equipos']?></strong></article><article class="metric-panel"><span>Tickets recientes</span><strong><?=$counts['tickets']?></strong></article></section>
<section class="card mt-3 no-print"><div class="card-header"><h2>Exportaciones CSV</h2></div><div class="card-body export-grid"><a href="<?=e(url('php/exportar.php?tipo=profesores'))?>"><strong>Profesores</strong><span>Datos básicos del turno</span></a><a href="<?=e(url('php/exportar.php?tipo=equipos'))?>"><strong>Equipos</strong><span>Inventario institucional</span></a><a href="<?=e(url('php/exportar.php?tipo=tickets'))?>"><strong>Tickets</strong><span>Incidencias del turno</span></a><a href="<?=e(url('php/exportar.php?tipo=sesiones'))?>"><strong>Historial de salas</strong><span>Ingresos y salidas</span></a></div></section>
<section class="card mt-3"><div class="card-header"><h2>Tickets recientes</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Fecha</th><th>Docente</th><th>Sala</th><th>Problema</th><th>Urgencia</th><th>Estado</th></tr></thead><tbody><?php foreach($tickets as $t):?><tr><td>#<?=(int)$t['id']?></td><td><?=e(format_datetime($t['creado_en']))?></td><td><?=e($t['docente'])?></td><td><?=e($t['sala'])?></td><td><?=e(ucwords(str_replace('_',' ',$t['tipo_problema'])))?></td><td><?=status_badge($t['urgencia'])?></td><td><?=status_badge($t['estado'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card mt-3"><div class="card-header"><h2>Uso reciente de salas</h2></div><div class="table-wrap"><table><thead><tr><th>Docente</th><th>Sala</th><th>Ingreso</th><th>Salida</th></tr></thead><tbody><?php foreach($sessions as $s):?><tr><td><?=e($s['docente'])?></td><td><?=e($s['sala'])?></td><td><?=e(format_datetime($s['checkin_en']))?></td><td><?=e(format_datetime($s['checkout_en']))?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require __DIR__.'/includes/footer.php';?>
